(function () {
var username = String(global.creator_username || '').trim().replace(/^wxchannels:/, '');
if (!username || username.indexOf('REPLACE_') >= 0) throw new Error('请先配置创作者 username');
if (!/@finder$/.test(username)) username += '@finder';
if (!(global.max_pages > 0) || !(global.max_videos > 0)) throw new Error('max_pages 和 max_videos 必须大于 0');
return {username: username};
})()

(function () {
var response = output.fetch_live.live_page;
if (!response || (response.errCode !== undefined && Number(response.errCode) !== 0) || (response.code !== undefined && Number(response.code) !== 0)) throw new Error('查询直播状态失败');
var data = response.data;
if (!data) throw new Error('直播响应缺少 data');
var live_objects = data.liveObjects;
if (!Array.isArray(live_objects)) {
  if (data.contact && data.contact.liveStatus !== undefined && Number(data.contact.liveStatus) === 0) live_objects = [];
  else throw new Error('直播响应缺少 data.liveObjects，无法判断是否开播');
}
if (data.BaseResponse && Number(data.BaseResponse.ret || 0) !== 0) throw new Error('查询直播 BaseResponse 返回错误');
var username = output.validate.creator.username;
var lives = live_objects.filter(function (item) { return String(item.username || (item.contact || {}).username || '') === username && String((item.liveInfo || {}).liveId || '') !== ''; });
return {is_live:lives.length > 0,username:username,live_id:lives.length ? String(lives[0].liveInfo.liveId) : ''};
})()
